# Kurs Automotive Security
from common import *

M1 = M("sec.m1", 1, "Bedrohungen und Angriffsflächen", "Warum Fahrzeuge Ziel von Angriffen sind, bekannte Fälle und typische Einfallstore.", [
 L("sec.m1.l1", "Warum Fahrzeuge angreifbar sind", 5, [
  "Ein modernes Fahrzeug ist ein vernetzter Computer auf Rädern: viele Steuergeräte, Mobilfunk, WLAN, Bluetooth, Funkschlüssel, Ladeanschluss und Apps. Jede Verbindung kann ein Einfallstor sein.",
  "## Was auf dem Spiel steht",
  "Sicherheit von Menschen (Eingriffe in Bremsen oder Lenkung), Diebstahl, Privatsphäre (Bewegungsprofile, Kontakte), Manipulation (Kilometerstand, Abgas, Leistung) und der Ruf des Herstellers.",
  "## Security ist nicht Safety",
  "Safety (funktionale Sicherheit) schützt vor zufälligen Fehlern und Ausfällen. Security (Angriffssicherheit) schützt vor absichtlichen Angriffen. Beides hängt zusammen: Ein Angriff kann ein Sicherheitsrisiko erzeugen."],
  ["Viele Schnittstellen = viele Einfallstore.", "Schutzgüter: Leben, Eigentum, Privatsphäre, Integrität, Ruf.", "Safety: zufällige Fehler; Security: absichtliche Angriffe."],
  [S_21434],
  [card("Safety", "Funktionale Sicherheit: Schutz vor Gefahren durch Fehlfunktionen."), card("Security", "Angriffssicherheit: Schutz vor absichtlichen Angriffen."), card("Angriffsfläche", "Gesamtheit der Schnittstellen, über die ein Angreifer ein System erreichen kann.")],
  [mc("Was unterscheidet Security von Safety?", ["Security schützt vor absichtlichen Angriffen", "Security schützt nur vor Rost", "Safety betrifft nur Software", "Es gibt keinen Unterschied"], "Safety betrifft zufällige Fehler und Ausfälle."),
   multi("Welche Schnittstellen vergrößern die Angriffsfläche?", ["Mobilfunk", "Bluetooth", "Funkschlüssel", "Der Lack"], [0, 1, 2], "Der Lack ist keine Datenschnittstelle."),
   mc("Was kann ein Angriff auf Fahrzeuge gefährden?", ["Menschenleben, Eigentum und Privatsphäre", "Nur den Kraftstoffverbrauch", "Nur das Radio", "Gar nichts"], "Die Schutzgüter sind vielfältig."),
   mc("Kann ein Security-Angriff ein Safety-Risiko erzeugen?", ["Ja, etwa bei Eingriffen in Bremsen", "Nein, nie", "Nur bei Elektroautos", "Nur in der Werkstatt"], "Deshalb müssen beide Disziplinen zusammenarbeiten."),
   mc("Was ist eine Angriffsfläche?", ["Alle erreichbaren Schnittstellen", "Die Karosserieoberfläche", "Die Reifenlauffläche", "Der Kofferraum"], "Je kleiner, desto besser.")]),
 L("sec.m1.l2", "Bekannte Fälle", 6, [
  "Einige Angriffe haben die Branche geprägt.",
  "## Fernangriff 2015",
  "Die Sicherheitsforscher Charlie Miller und Chris Valasek zeigten 2015, dass sie einen Jeep Cherokee über das Mobilfunknetz erreichen konnten: über eine Lücke im Infotainmentsystem bis auf den CAN-Bus, mit Einfluss auf Fahrfunktionen. Der Hersteller rief rund 1,4 Millionen Fahrzeuge zurück.",
  "## Relay-Angriffe auf Keyless",
  "Diebe verlängern mit zwei Funkgeräten die Reichweite des Schlüssels im Haus bis zum Auto. Das Fahrzeug glaubt, der Schlüssel sei nah, und öffnet. Gegenmittel sind Laufzeitmessung (Ultra-Wideband) oder Schlüssel mit Bewegungssensor.",
  "## CAN-Injection",
  "Diebe öffneten etwa Kabel hinter einem Scheinwerfer und speisten Botschaften direkt in einen Bus ein, die das Fahrzeug entriegelten. Das zeigt: Auch der physische Zugang zu Leitungen ist eine Angriffsfläche, und Botschaften ohne Authentisierung lassen sich fälschen."],
  ["2015: Fernangriff über Infotainment bis CAN, 1,4 Mio. Rückrufe.", "Relay-Angriffe verlängern die Schlüsselreichweite.", "CAN-Injection: ungeschützte Botschaften lassen sich fälschen."],
  [S_21434, S_R155],
  [card("Relay-Angriff", "Verlängerung der Funkreichweite eines Schlüssels mit zwei Geräten, um ein Fahrzeug zu öffnen."), card("CAN-Injection", "Einspeisen gefälschter Botschaften direkt in einen Fahrzeugbus."), card("UWB", "Ultra-Wideband: Funktechnik mit genauer Laufzeitmessung gegen Relay-Angriffe.")],
  [mc("Was war das Einfallstor beim Fernangriff 2015?", ["Das Infotainmentsystem über Mobilfunk", "Die OBD-Buchse", "Der Tankdeckel", "Ein Reifendrucksensor"], "Von dort ging es bis auf den CAN-Bus."),
   mc("Wie funktioniert ein Relay-Angriff?", ["Funkreichweite des Schlüssels wird verlängert", "Schlüssel wird kopiert und neu gefräst", "Die Batterie wird abgeklemmt", "Das Fenster wird eingeschlagen"], "Das Auto hält den Schlüssel für nah."),
   mc("Was hilft gegen Relay-Angriffe?", ["Laufzeitmessung mit Ultra-Wideband", "Lautere Hupe", "Größere Schlüssel", "Mehr Spiegel"], "Die Signallaufzeit verrät die Entfernung."),
   mc("Was zeigte CAN-Injection?", ["Ungeschützte Botschaften lassen sich fälschen", "CAN ist abhörsicher", "Scheinwerfer sind unwichtig", "Fahrzeuge brauchen keine Busse"], "Authentisierte Botschaften (SecOC) helfen."),
   mc("Wie viele Fahrzeuge wurden nach 2015 zurückgerufen?", ["Etwa 1,4 Millionen", "Etwa 100", "Keine", "Etwa 50 Millionen"], "Es war der erste große Cyber-Rückruf.")]),
 L("sec.m1.l3", "Angreifer und Angriffspfade", 6, [
  "Wer greift an und wie?",
  "## Angreifertypen",
  "Kriminelle (Diebstahl, Erpressung), Tuner und Halter (Leistung, Kilometerstand, Abgas), Forscher (Lücken finden und melden), staatliche Akteure. Ihre Mittel und Motive unterscheiden sich stark.",
  "## Pfade",
  "Fern (Mobilfunk, Backend, App), nah (Bluetooth, WLAN, Schlüsselfunk, Reifendrucksensoren, V2X), mit physischem Zugang (OBD-Buchse, Ladeanschluss, Busleitungen, Ausbau von Steuergeräten) und über die Lieferkette (manipulierte Bauteile oder Software).",
  "## Der typische Weg",
  "Angreifer suchen einen erreichbaren Einstieg, verschaffen sich dort Kontrolle und bewegen sich dann weiter in Richtung kritischer Funktionen (laterale Bewegung). Deshalb setzt man auf mehrere Schutzschichten: Selbst wenn eine fällt, halten die anderen (Defense in Depth)."],
  ["Angreifer: Kriminelle, Halter/Tuner, Forscher, Staaten.", "Pfade: fern, nah, physisch, Lieferkette.", "Defense in Depth: mehrere Schutzschichten."],
  [S_21434],
  [card("Defense in Depth", "Mehrere unabhängige Schutzschichten, damit ein einzelner Durchbruch nicht reicht."), card("Laterale Bewegung", "Vorgehen eines Angreifers, sich vom Einstiegspunkt zu weiteren Systemen vorzuarbeiten.")],
  [mc("Was bedeutet Defense in Depth?", ["Mehrere Schutzschichten", "Ein einziger starker Schutz", "Schutz nur im Motorraum", "Tiefe Garage"], "Fällt eine Schicht, halten die anderen."),
   mc("Welcher Angreifertyp manipuliert oft den Kilometerstand?", ["Halter oder Händler mit Betrugsabsicht", "Sicherheitsforscher", "Staatliche Akteure", "Niemand"], "Motive unterscheiden sich stark."),
   mc("Was ist ein physischer Angriffspfad?", ["Die OBD-Buchse", "Das Mobilfunknetz", "Die Smartphone-App", "Das Backend"], "Dafür braucht man Zugang zum Fahrzeug."),
   mc("Was beschreibt laterale Bewegung?", ["Vom Einstieg zu weiteren Systemen vorarbeiten", "Seitliches Einparken", "Spurwechsel auf der Autobahn", "Bewegung der Lenkung"], "Deshalb trennt man Netze."),
   mc("Was ist ein Lieferketten-Angriff?", ["Manipulierte Bauteile oder Software", "Diebstahl eines Lkw", "Stau auf der Autobahn", "Verspätete Lieferung"], "Der Angriff steckt schon im Produkt.")])
])

M2 = M("sec.m2", 1, "Regeln: R155, R156, ISO/SAE 21434", "Was Gesetzgeber und Normen verlangen.", [
 L("sec.m2.l1", "UN R155: Cybersecurity-Managementsystem", 6, [
  "Die UN-Regelung Nr. 155 verpflichtet Hersteller, ein Cybersecurity-Managementsystem (CSMS) zu betreiben und jeden Fahrzeugtyp gegen Cyberangriffe abzusichern.",
  "## Geltung in der EU",
  "Für neue Fahrzeugtypen gilt R155 in der EU seit Juli 2022, für alle neu zugelassenen Fahrzeuge der betroffenen Klassen seit Juli 2024. Fahrzeuge ohne Nachweis dürfen nicht neu zugelassen werden, was zu Produktionsstopps einzelner älterer Modelle führte.",
  "## Was gefordert wird",
  "Prozesse über den gesamten Lebenszyklus: Risiken erkennen und bewerten, Schutzmaßnahmen umsetzen, testen, Angriffe im Feld überwachen und auf neue Bedrohungen reagieren, auch bei Lieferanten. Ein Anhang listet typische Bedrohungen und Gegenmaßnahmen.",
  "## Zwei Nachweise",
  "Das CSMS des Herstellers wird zertifiziert (gilt drei Jahre). Für jeden Fahrzeugtyp wird zusätzlich geprüft, ob die Risiken angemessen behandelt sind."],
  ["R155: CSMS beim Hersteller und abgesicherte Fahrzeugtypen.", "EU: neue Typen seit 07/2022, alle Neuzulassungen seit 07/2024.", "Lebenszyklus: erkennen, schützen, testen, überwachen, reagieren."],
  [S_R155],
  [card("CSMS", "Cyber Security Management System: Organisation und Prozesse eines Herstellers für Cybersecurity."), card("UN R155", "UN-Regelung zu Cybersecurity und CSMS für Fahrzeuge.")],
  [mc("Seit wann gilt R155 für alle neu zugelassenen Fahrzeuge (betroffene Klassen) in der EU?", ["Juli 2024", "Juli 2022", "Januar 2030", "Januar 2015"], "Neue Typen seit Juli 2022."),
   mc("Was ist ein CSMS?", ["Organisation und Prozesse für Cybersecurity", "Ein Steuergerät", "Ein Fehlercode", "Eine Firewall"], "Es umfasst den gesamten Lebenszyklus."),
   mc("Wie lange gilt ein CSMS-Zertifikat?", ["Drei Jahre", "Einen Tag", "Für immer", "Zehn Jahre"], "Danach wird erneut geprüft."),
   mc("Was folgte für manche ältere Modelle aus R155?", ["Produktionsstopp", "Steuersenkung", "Höhere Leistung", "Nichts"], "Ohne Nachweis keine Neuzulassung."),
   mc("Gilt R155 auch für Lieferanten?", ["Hersteller müssen die Lieferkette einbeziehen", "Nein, Lieferanten sind ausgenommen", "Nur für Reifenhersteller", "Nur außerhalb der EU"], "Risiken in der Lieferkette müssen behandelt werden.")], vol=True),
 L("sec.m2.l2", "UN R156: Software-Updates", 6, [
  "Die UN-Regelung Nr. 156 regelt Software-Updates, in der Werkstatt wie Over-the-Air. Sie gilt in der EU zu denselben Stichtagen wie R155.",
  "## SUMS",
  "Hersteller brauchen ein Software-Update-Managementsystem (SUMS): Sie müssen wissen, welche Software in welchem Fahrzeug steckt, Updates absichern, Abhängigkeiten prüfen und bewerten, ob ein Update genehmigungsrelevante Funktionen ändert.",
  "## RXSWIN",
  "Die Regulation X Software Identification Number kennzeichnet Software, die für eine bestimmte Typgenehmigung relevant ist. Ändert ein Update diese Software, ändert sich die RXSWIN, und das muss dokumentiert sein.",
  "## Für OTA-Updates",
  "Fahrer müssen informiert werden, das Update darf die Sicherheit nicht gefährden, und bei Fehlschlag muss das Fahrzeug in einen sicheren Zustand zurückkehren können. Benötigt ein Update besondere Bedingungen (etwa Fahrzeug steht), muss es diese sicherstellen."],
  ["R156: SUMS für sichere, nachvollziehbare Updates.", "RXSWIN kennzeichnet genehmigungsrelevante Software.", "OTA: Information, Sicherheit, Rückfallebene."],
  [S_R156],
  [card("SUMS", "Software Update Management System nach UN R156."), card("RXSWIN", "Regulation X Software Identification Number: Kennung genehmigungsrelevanter Software.")],
  [mc("Was kennzeichnet die RXSWIN?", ["Genehmigungsrelevante Software", "Die Fahrgestellnummer", "Die Reifengröße", "Den Kilometerstand"], "Sie ändert sich mit relevanten Updates."),
   mc("Was muss bei einem fehlgeschlagenen OTA-Update möglich sein?", ["Rückkehr in einen sicheren Zustand", "Nichts", "Weiterfahren ohne Bremsen", "Automatische Abmeldung"], "Das Fahrzeug darf nicht unsicher werden."),
   mc("Was muss ein SUMS unter anderem wissen?", ["Welche Software in welchem Fahrzeug steckt", "Wer das Fahrzeug fährt", "Wo der Fahrer wohnt", "Welche Musik läuft"], "Ohne Übersicht keine sicheren Updates."),
   mc("Gilt R156 auch für Updates in der Werkstatt?", ["Ja, für alle Update-Wege", "Nein, nur für OTA", "Nur für Elektroautos", "Nur für Lkw"], "Werkstatt und OTA sind erfasst."),
   mc("Ab wann gilt R156 in der EU für alle Neuzulassungen?", ["Juli 2024", "Juli 2020", "Januar 2035", "Nie"], "Zu denselben Stichtagen wie R155.")], vol=True),
 L("sec.m2.l3", "ISO/SAE 21434", 6, [
  "Die Norm ISO/SAE 21434 (2021) beschreibt, wie Cybersecurity im Engineering umgesetzt wird. Sie ist der wichtigste Weg, die Anforderungen von R155 praktisch zu erfüllen.",
  "## Inhalte",
  "Organisation und Kultur, Risikomanagement (TARA), Konzeptphase mit Cybersecurity-Zielen, Produktentwicklung mit Anforderungen und Verifikation, Validierung, Produktion, Betrieb und Wartung inklusive Schwachstellenmanagement bis zur Außerbetriebnahme.",
  "## CAL",
  "Ähnlich wie ASIL bei der funktionalen Sicherheit gibt es Cybersecurity Assurance Levels (CAL 1 bis 4). Sie legen fest, wie gründlich Maßnahmen umgesetzt und geprüft werden. Die Norm führt sie als informativen Ansatz.",
  "## Zusammenspiel",
  "ISO/SAE 21434 sagt nicht, welche Verschlüsselung zu nutzen ist, sondern wie man systematisch zu angemessenen Maßnahmen kommt. Sie arbeitet eng mit ISO 26262 zusammen, weil Angriffe Sicherheitsfolgen haben können."],
  ["ISO/SAE 21434: Cybersecurity-Engineering über den Lebenszyklus.", "TARA ist das Herzstück; CAL 1–4 als Gründlichkeitsstufen.", "Sagt wie, nicht welche Technik; eng verzahnt mit ISO 26262."],
  [S_21434],
  [card("ISO/SAE 21434", "Norm für Cybersecurity-Engineering von Straßenfahrzeugen (2021)."), card("CAL", "Cybersecurity Assurance Level 1–4: Gründlichkeit von Maßnahmen und Prüfungen."), card("Cybersecurity-Ziel", "Oberste Schutzanforderung, abgeleitet aus der Risikoanalyse.")],
  [mc("Was ist das Herzstück von ISO/SAE 21434?", ["Die Risikoanalyse TARA", "Eine bestimmte Verschlüsselung", "Ein Steckertyp", "Ein Fehlercode"], "Daraus folgen Ziele und Maßnahmen."),
   mc("Was ist ein CAL?", ["Gründlichkeitsstufe für Cybersecurity", "Ein Kalibrierwert", "Eine Abgasstufe", "Ein Bussystem"], "Ähnlich der Idee hinter ASIL."),
   mc("Schreibt die Norm konkrete Algorithmen vor?", ["Nein, sie beschreibt das Vorgehen", "Ja, nur AES", "Ja, nur RSA", "Ja, nur Passwörter"], "Maßnahmen folgen aus der Analyse."),
   mc("Mit welcher Norm arbeitet 21434 eng zusammen?", ["ISO 26262", "ISO 9001 allein", "SAE J1962", "Euro 7"], "Angriffe können Safety-Folgen haben."),
   mc("Endet die Norm mit dem Produktionsstart?", ["Nein, sie reicht bis zur Außerbetriebnahme", "Ja", "Ja, mit der Typgenehmigung", "Ja, mit dem ersten Update"], "Betrieb und Schwachstellenmanagement gehören dazu.")])
])

M3 = M("sec.m3", 2, "Risiken analysieren: TARA", "Schutzgüter, Bedrohungen, Angriffspfade, Bewertung und Maßnahmen.", [
 L("sec.m3.l1", "Schutzgüter und Schadensszenarien", 6, [
  "Die Threat Analysis and Risk Assessment (TARA) beginnt mit der Frage: Was wollen wir schützen?",
  "## Schutzgüter",
  "Schutzgüter (Assets) sind zum Beispiel Botschaften auf einem Bus, Schlüssel im Steuergerät, Software, Kalibrierdaten oder persönliche Daten. Für jedes Gut wird festgelegt, welche Eigenschaft wichtig ist: Vertraulichkeit, Integrität oder Verfügbarkeit.",
  "## Schadensszenarien",
  "Was passiert, wenn eine Eigenschaft verletzt wird? Wird die Integrität der Bremsbotschaft verletzt, kann das Fahrzeug ungewollt bremsen. Wird die Vertraulichkeit der Standortdaten verletzt, entsteht ein Bewegungsprofil.",
  "## Auswirkung bewerten",
  "Die Auswirkung wird in vier Kategorien bewertet: Sicherheit (Safety), finanziell, betrieblich und Privatsphäre, jeweils von vernachlässigbar bis schwerwiegend."],
  ["TARA startet mit Schutzgütern und ihren Eigenschaften (V, I, V).", "Schadensszenario: Folge einer Verletzung.", "Auswirkung: Safety, finanziell, betrieblich, Privatsphäre."],
  [S_21434],
  [card("TARA", "Threat Analysis and Risk Assessment: Bedrohungs- und Risikoanalyse."), card("Asset", "Schutzgut, z. B. Schlüssel, Software, Botschaften oder Daten."), card("CIA", "Confidentiality, Integrity, Availability: Vertraulichkeit, Integrität, Verfügbarkeit.")],
  [mc("Womit beginnt eine TARA?", ["Mit den Schutzgütern", "Mit dem Kauf von Software", "Mit einem Penetrationstest", "Mit der Werbung"], "Erst festlegen, was geschützt werden soll."),
   mc("Welche Eigenschaft ist bei einer Bremsbotschaft besonders wichtig?", ["Integrität", "Vertraulichkeit", "Farbe", "Lautstärke"], "Gefälschte Werte wären gefährlich."),
   mc("Welche Eigenschaft ist bei Standortdaten besonders wichtig?", ["Vertraulichkeit", "Integrität", "Verfügbarkeit", "Lautstärke"], "Sonst drohen Bewegungsprofile."),
   multi("In welchen Kategorien wird die Auswirkung bewertet?", ["Safety", "Finanziell", "Privatsphäre", "Lackqualität"], [0, 1, 2], "Dazu kommt betrieblich."),
   mc("Was ist ein Schadensszenario?", ["Folge einer verletzten Schutzeigenschaft", "Ein Unfallbericht der Polizei", "Ein Werkstattauftrag", "Eine Garantieleistung"], "Etwa: ungewolltes Bremsen.")]),
 L("sec.m3.l2", "Bedrohungen und Angriffspfade", 6, [
  "Als Nächstes fragt man: Wie könnte jemand das Schutzgut angreifen?",
  "## STRIDE",
  "Ein bewährtes Hilfsmittel ist STRIDE: Spoofing (vortäuschen einer Identität), Tampering (Manipulation), Repudiation (Abstreiten), Information Disclosure (Ausspähen), Denial of Service (Lahmlegen), Elevation of Privilege (Rechte ausweiten).",
  "## Angriffspfade",
  "Für jede Bedrohung wird beschrieben, über welche Schritte ein Angreifer sie umsetzen könnte, zum Beispiel: Bluetooth-Lücke im Infotainment → Kontrolle über das Infotainment → gefälschte Botschaft über das Gateway → Bremsbotschaft.",
  "## Machbarkeit",
  "Die Angriffsmachbarkeit wird bewertet, etwa nach benötigter Zeit, Fachwissen, Wissen über das Ziel, Gelegenheit (Zugang) und Ausrüstung. Ein Angriff, der Wochen, Spezialwissen und teure Geräte braucht, ist weniger wahrscheinlich als einer mit frei verfügbaren Werkzeugen."],
  ["STRIDE: Spoofing, Tampering, Repudiation, Information Disclosure, DoS, Elevation of Privilege.", "Angriffspfade beschreiben Schritte zum Ziel.", "Machbarkeit: Zeit, Wissen, Zugang, Ausrüstung."],
  [S_21434],
  [card("STRIDE", "Bedrohungskategorien: Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege."), card("Angriffsmachbarkeit", "Bewertung, wie leicht ein Angriff umsetzbar ist (Zeit, Wissen, Zugang, Ausrüstung).")],
  [mc("Wofür steht das S in STRIDE?", ["Spoofing", "Safety", "Software", "Speed"], "Vortäuschen einer Identität."),
   mc("Was ist Tampering?", ["Manipulation von Daten oder Software", "Ausspähen von Daten", "Lahmlegen eines Dienstes", "Abstreiten einer Handlung"], "Das T in STRIDE."),
   mc("Was bedeutet Denial of Service?", ["Einen Dienst lahmlegen", "Rechte ausweiten", "Daten verschlüsseln", "Identität vortäuschen"], "Die Verfügbarkeit wird angegriffen."),
   multi("Was fließt in die Angriffsmachbarkeit ein?", ["Benötigte Zeit", "Fachwissen", "Zugang", "Lieblingsfarbe des Angreifers"], [0, 1, 2], "Dazu Ausrüstung und Zielwissen."),
   mc("Welcher Angriff ist wahrscheinlicher?", ["Einer mit frei verfügbaren Werkzeugen", "Einer, der Spezialchips für Millionen braucht", "Einer, der Jahre dauert", "Einer, der Insiderwissen erfordert"], "Geringe Hürden erhöhen die Machbarkeit.")]),
 L("sec.m3.l3", "Risiko behandeln", 6, [
  "Aus Auswirkung und Machbarkeit ergibt sich das Risiko, oft über eine Matrix.",
  "## Vier Optionen",
  "Vermeiden (Funktion weglassen oder anders gestalten), reduzieren (Schutzmaßnahmen), teilen (etwa über Verträge oder Versicherungen) und akzeptieren (wenn das Restrisiko vertretbar ist, mit Begründung).",
  "## Cybersecurity-Ziele und -Anforderungen",
  "Für reduzierte Risiken werden Ziele formuliert, etwa „Bremsbotschaften dürfen nicht unbemerkt gefälscht werden können“. Daraus folgen technische Anforderungen, etwa SecOC mit 128-Bit-Schlüsseln und Freshness-Werten.",
  "## Iterativ",
  "Eine TARA ist nie fertig. Neue Angriffstechniken, neue Schwachstellen oder Funktionsänderungen erfordern eine Neubewertung über den ganzen Lebenszyklus."],
  ["Risiko = Auswirkung × Machbarkeit (Matrix).", "Optionen: vermeiden, reduzieren, teilen, akzeptieren.", "Ziele → Anforderungen; TARA wird laufend aktualisiert."],
  [S_21434],
  [card("Risikobehandlung", "Entscheidung, ein Risiko zu vermeiden, zu reduzieren, zu teilen oder zu akzeptieren."), card("Restrisiko", "Risiko, das nach Maßnahmen verbleibt und begründet akzeptiert wird.")],
  [multi("Welche Optionen der Risikobehandlung gibt es?", ["Vermeiden", "Reduzieren", "Akzeptieren", "Ignorieren ohne Begründung"], [0, 1, 2], "Akzeptieren braucht immer eine Begründung; dazu kommt Teilen."),
   mc("Was ist eine typische Anforderung aus dem Ziel „Bremsbotschaften nicht fälschbar“?", ["Botschaften mit MAC absichern (SecOC)", "Bremsen lauter machen", "Größere Bremsscheiben", "Mehr Bremsflüssigkeit"], "Ein Message Authentication Code verhindert Fälschungen."),
   mc("Wann muss eine TARA neu bewertet werden?", ["Bei neuen Angriffen oder Änderungen", "Nie", "Nur beim Verkauf", "Nur bei Unfällen"], "Sie begleitet den ganzen Lebenszyklus."),
   mc("Woraus ergibt sich das Risiko?", ["Aus Auswirkung und Machbarkeit", "Aus der Fahrzeugfarbe", "Aus der Motorleistung", "Aus dem Verkaufspreis"], "Oft über eine Matrix."),
   mc("Was bedeutet „Risiko vermeiden“?", ["Funktion weglassen oder anders gestalten", "Eine Versicherung abschließen", "Das Risiko hinnehmen", "Das Risiko verschweigen"], "Ohne Angriffsfläche kein Angriff.")])
])

M4 = M("sec.m4", 2, "Kryptografie im Fahrzeug", "Schlüssel und Hardware-Sicherheit, Secure Boot, gesicherte Botschaften und PKI.", [
 L("sec.m4.l1", "Bausteine der Kryptografie", 6, [
  "Kryptografie liefert die Werkzeuge, mit denen Fahrzeuge Vertraulichkeit, Integrität und Echtheit sichern.",
  "## Symmetrisch",
  "Beide Seiten teilen einen Schlüssel, etwa AES mit 128 Bit. Schnell und für Steuergeräte gut geeignet, aber der Schlüssel muss sicher verteilt und geschützt werden. Ein MAC (zum Beispiel CMAC auf AES-Basis) zeigt, dass eine Nachricht unverändert von jemandem mit dem Schlüssel stammt.",
  "## Asymmetrisch",
  "Ein Schlüsselpaar aus öffentlichem und privatem Schlüssel, etwa RSA oder elliptische Kurven (ECDSA). Mit dem privaten Schlüssel signiert der Hersteller Software, mit dem öffentlichen prüft das Steuergerät. Den öffentlichen Schlüssel darf jeder kennen.",
  "## Hashfunktionen",
  "Eine Hashfunktion wie SHA-256 bildet beliebige Daten auf einen kurzen Fingerabdruck ab. Schon eine kleine Änderung ergibt einen völlig anderen Hash. Signaturen werden über den Hash gebildet."],
  ["Symmetrisch (AES, CMAC): schnell, gemeinsamer Schlüssel.", "Asymmetrisch (RSA, ECDSA): signieren mit privatem, prüfen mit öffentlichem Schlüssel.", "Hash (SHA-256): Fingerabdruck der Daten."],
  [S_21434, S_AUTOSAR],
  [card("MAC", "Message Authentication Code: prüft Integrität und Herkunft mit gemeinsamem Schlüssel."), card("Digitale Signatur", "Mit privatem Schlüssel erzeugt, mit öffentlichem Schlüssel prüfbar."), card("SHA-256", "Kryptografische Hashfunktion mit 256 Bit Ausgabe.")],
  [mc("Womit prüft ein Steuergerät eine Software-Signatur?", ["Mit dem öffentlichen Schlüssel des Herstellers", "Mit dem privaten Schlüssel des Herstellers", "Mit dem Passwort des Fahrers", "Mit der Fahrgestellnummer"], "Der private Schlüssel bleibt beim Hersteller."),
   mc("Was ist ein Vorteil symmetrischer Verfahren?", ["Sie sind schnell", "Man braucht keinen Schlüssel", "Jeder darf den Schlüssel kennen", "Sie sind unknackbar ohne Schlüsselschutz"], "Gut für Steuergeräte mit wenig Rechenleistung."),
   mc("Was passiert mit dem Hash bei kleiner Datenänderung?", ["Er ändert sich völlig", "Er bleibt gleich", "Er wird kürzer", "Er wird null"], "Das macht Manipulation erkennbar."),
   mc("Was zeigt ein MAC?", ["Nachricht unverändert und vom Schlüsselinhaber", "Die Uhrzeit", "Die Bitrate", "Die Temperatur"], "Integrität und Herkunft."),
   mc("Darf der öffentliche Schlüssel bekannt sein?", ["Ja", "Nein, niemals", "Nur dem Fahrer", "Nur der Werkstatt"], "Nur der private Schlüssel ist geheim.")]),
 L("sec.m4.l2", "HSM und Secure Boot", 6, [
  "Schlüssel nützen nur, wenn sie geschützt sind. Deshalb haben moderne Mikrocontroller ein Hardware-Sicherheitsmodul (HSM).",
  "## Das HSM",
  "Ein abgeschotteter Bereich mit eigenem Prozessor, Speicher und Krypto-Beschleunigern. Schlüssel verlassen das HSM nicht; die Anwendung bittet das HSM nur, etwas zu verschlüsseln, zu signieren oder zu prüfen. Zusätzlich liefert es echte Zufallszahlen.",
  "## Secure Boot",
  "Beim Start prüft das HSM oder ein unveränderlicher Startcode, ob die Software unverändert ist, etwa per Signatur oder MAC. Nur dann startet sie. Eine Vertrauenskette (Chain of Trust) prüft jede Stufe die nächste.",
  "## Secure Flashing und Debug-Schutz",
  "Beim Flashen wird nur signierte Software akzeptiert. Debug-Schnittstellen wie JTAG werden in Serie gesperrt oder durch Authentisierung geschützt, damit niemand über sie Speicher und Schlüssel ausliest."],
  ["HSM: Schlüssel bleiben drin; Krypto und Zufall in Hardware.", "Secure Boot: Vertrauenskette prüft jede Stufe.", "Secure Flashing; Debug-Schnittstellen sperren."],
  [S_AUTOSAR, S_21434],
  [card("HSM", "Hardware Security Module: geschützter Bereich im Controller für Schlüssel und Kryptografie."), card("Chain of Trust", "Vertrauenskette: Jede Startstufe prüft die Echtheit der nächsten."), card("JTAG", "Debug-Schnittstelle von Prozessoren; in Serie gesperrt oder geschützt.")],
  [mc("Verlassen Schlüssel das HSM?", ["Nein, das HSM rechnet selbst", "Ja, bei jedem Start", "Ja, für die Werkstatt", "Nur nachts"], "Die Anwendung bekommt nur Ergebnisse."),
   mc("Was ist eine Chain of Trust?", ["Jede Startstufe prüft die nächste", "Eine Kette am Lenkrad", "Eine Liste der Lieferanten", "Ein Fehlerspeicher"], "Vom unveränderlichen Startcode bis zur Anwendung."),
   mc("Warum sperrt man JTAG in Serie?", ["Damit niemand Speicher und Schlüssel ausliest", "Um Strom zu sparen", "Damit der Bus schneller wird", "Wegen der Abgasnorm"], "Debug-Zugänge sind mächtige Angriffspunkte."),
   mc("Was liefert ein HSM zusätzlich?", ["Echte Zufallszahlen", "Kraftstoff", "Musik", "Licht"], "Wichtig für Seeds, Schlüssel und Nonces."),
   mc("Was prüft Secure Boot?", ["Ob die Software unverändert ist", "Ob der Fahrer angeschnallt ist", "Ob der Tank voll ist", "Ob die Reifen neu sind"], "Per Signatur oder MAC.")]),
 L("sec.m4.l3", "Gesicherte Botschaften und PKI", 7, [
  "Klassische CAN-Botschaften haben keine Absenderprüfung. Jeder am Bus kann alles senden.",
  "## SecOC",
  "AUTOSAR Secure Onboard Communication (SecOC) hängt an kritische Botschaften einen gekürzten MAC und einen Freshness-Wert (Zähler oder Zeit). Der Empfänger prüft beides. Gefälschte Botschaften fallen am falschen MAC auf, wieder eingespielte alte Botschaften (Replay) am veralteten Freshness-Wert.",
  "## Abwägungen",
  "Auf klassischem CAN mit 8 Byte ist Platz knapp, deshalb werden MACs gekürzt, etwa auf 24 bis 64 Bit. CAN FD und Ethernet lassen mehr Raum. Schlüssel werden pro Fahrzeug unterschiedlich verteilt, damit ein ausgelesener Schlüssel nicht alle Fahrzeuge öffnet.",
  "## PKI",
  "Für Kommunikation mit Backend, Werkstatt oder anderen Fahrzeugen nutzt man eine Public-Key-Infrastruktur: Zertifikate bestätigen, dass ein öffentlicher Schlüssel zu einem bestimmten Teilnehmer gehört. Gesperrte Zertifikate kommen auf Sperrlisten. Auf Ethernet schützen TLS oder MACsec die Verbindungen."],
  ["SecOC: gekürzter MAC + Freshness gegen Fälschung und Replay.", "Fahrzeugindividuelle Schlüssel begrenzen Schäden.", "PKI mit Zertifikaten; TLS/MACsec auf Ethernet."],
  [S_AUTOSAR, S_21434],
  [card("SecOC", "AUTOSAR Secure Onboard Communication: MAC und Freshness für Busbotschaften."), card("Freshness-Wert", "Zähler oder Zeitstempel, der wiederholte alte Botschaften erkennbar macht."), card("Replay-Angriff", "Erneutes Einspielen einer aufgezeichneten, echten Botschaft."), card("PKI", "Public-Key-Infrastruktur: Zertifikate, Zertifizierungsstellen, Sperrlisten.")],
  [mc("Wogegen schützt der Freshness-Wert?", ["Replay-Angriffe", "Rost", "Kurzschlüsse", "Überhitzung"], "Alte Botschaften haben veraltete Zähler."),
   mc("Warum werden MACs auf klassischem CAN gekürzt?", ["Wenig Platz im 8-Byte-Frame", "Damit sie unsicherer werden", "Weil CAN keine Zahlen kann", "Wegen der Abgasnorm"], "Ein Kompromiss aus Sicherheit und Platz."),
   mc("Warum nutzt man fahrzeugindividuelle Schlüssel?", ["Ein ausgelesener Schlüssel öffnet nicht alle Fahrzeuge", "Weil es billiger ist", "Weil Schlüssel sonst rosten", "Damit Updates schneller sind"], "Skalierbare Angriffe werden verhindert."),
   mc("Was bestätigt ein Zertifikat?", ["Dass ein öffentlicher Schlüssel zu einem Teilnehmer gehört", "Die Fahrzeugfarbe", "Den Abgaswert", "Die Uhrzeit"], "Ausgestellt von einer Zertifizierungsstelle."),
   mc("Was schützt Ethernet-Verbindungen?", ["TLS oder MACsec", "LIN", "Klemme 15", "Bitstuffing"], "Auf verschiedenen Schichten.")])
])

M5 = M("sec.m5", 3, "Diagnose, Updates und Schnittstellen schützen", "Zugriffsschutz, sichere Updates, Gateway und Funkschnittstellen.", [
 L("sec.m5.l1", "Diagnosezugang absichern", 6, [
  "Diagnose ist mächtig: Software laden, Codierung ändern, Stellglieder bewegen. Deshalb ist sie ein beliebtes Angriffsziel, etwa für Kilometermanipulation oder Diebstahl über das Anlernen neuer Schlüssel.",
  "## Klassisch: Seed und Key",
  "UDS SecurityAccess (0x27) mit geheimem Algorithmus schützt seit Jahrzehnten. Schwäche: Ist der Algorithmus bekannt, ist der Schutz weg, und er steckt in vielen Testern.",
  "## Modern: Authentisierung",
  "UDS Authentication (0x29) mit Zertifikaten und rollenbasierten Rechten. Der Tester bekommt vom Backend des Herstellers ein Zertifikat für einen bestimmten Zweck und Zeitraum, oft nach Anmeldung der Werkstatt.",
  "## Weitere Maßnahmen",
  "Das Gateway filtert Diagnosezugriffe von der OBD-Buchse, kritische Funktionen erfordern zusätzlich eine Online-Freigabe, und Zugriffe werden protokolliert."],
  ["Diagnose ist mächtig und daher Angriffsziel.", "0x27 Seed/Key: Algorithmus kann durchsickern.", "0x29 mit Zertifikaten und Rollen; Gateway filtert, Zugriffe werden protokolliert."],
  [S_14229, S_21434],
  [card("Rollenbasierte Rechte", "Zugriffsrechte abhängig von der Rolle, z. B. Werkstatt, Entwicklung, Prüfstelle."), card("Online-Freigabe", "Freischaltung einer kritischen Funktion über das Backend des Herstellers.")],
  [mc("Warum ist 0x27 mit geheimem Algorithmus problematisch?", ["Der Algorithmus kann durchsickern", "Er ist zu langsam", "Er braucht Ethernet", "Er ist nicht genormt"], "Er steckt in vielen Testern."),
   mc("Was bietet 0x29?", ["Zertifikate und Rollen", "Mehr Bitrate", "Längere Kabel", "Keine Sicherheit"], "Rechte für Zweck und Zeitraum."),
   mc("Was tut das Gateway beim Diagnosezugriff?", ["Es filtert Zugriffe", "Es löscht alle Fehler", "Es lädt die Batterie", "Es misst Abgase"], "Nicht jeder darf an jedes Steuergerät."),
   mc("Welche Manipulation ist ein typisches Ziel von Angriffen auf Diagnose?", ["Kilometerstand ändern", "Reifen aufpumpen", "Scheiben reinigen", "Licht einschalten"], "Auch Schlüssel anlernen für Diebstahl."),
   mc("Warum protokolliert man Diagnosezugriffe?", ["Um Missbrauch nachvollziehen zu können", "Um Speicher zu füllen", "Für die Werbung", "Wegen der Musik"], "Nachvollziehbarkeit schreckt ab und hilft bei Vorfällen.")]),
 L("sec.m5.l2", "Sichere Updates", 6, [
  "Updates schließen Lücken, sind aber selbst ein Einfallstor, wenn sie nicht abgesichert sind.",
  "## Ende-zu-Ende geschützt",
  "Der Hersteller signiert das Update in einer geschützten Umgebung. Das Fahrzeug prüft die Signatur im Steuergerät, nicht nur im Backend oder in der Telematikeinheit. So hilft auch ein kompromittierter Übertragungsweg dem Angreifer nicht.",
  "## Rollback-Schutz",
  "Angreifer könnten eine alte Software mit bekannter Lücke einspielen. Ein Versionszähler im geschützten Speicher verhindert, dass ältere Versionen installiert werden (Anti-Rollback).",
  "## Uptane",
  "Für OTA gibt es Frameworks wie Uptane: Mehrere Rollen und Schlüssel signieren getrennt, sodass auch ein einzelner gestohlener Schlüssel nicht ausreicht, um manipulierte Updates zu verteilen."],
  ["Signatur im Ziel-Steuergerät prüfen (Ende-zu-Ende).", "Anti-Rollback: keine älteren Versionen.", "Uptane: getrennte Rollen und Schlüssel für OTA."],
  [S_R156, S("Uptane: Framework zur Absicherung von Software-Updates im Fahrzeug", "https://uptane.org/")],
  [card("Anti-Rollback", "Schutz gegen das Installieren älterer, verwundbarer Softwareversionen."), card("Uptane", "Offenes Framework für sichere OTA-Updates mit getrennten Rollen und Schlüsseln.")],
  [mc("Wo sollte die Update-Signatur geprüft werden?", ["Im Ziel-Steuergerät", "Nur im Backend", "Nur im Smartphone", "Gar nicht"], "Ende-zu-Ende-Schutz."),
   mc("Wogegen schützt Anti-Rollback?", ["Einspielen alter, verwundbarer Versionen", "Rollen des Fahrzeugs am Berg", "Rost", "Diebstahl der Räder"], "Ein Versionszähler verhindert Rückschritte."),
   mc("Was ist die Idee hinter Uptane?", ["Getrennte Rollen und Schlüssel", "Ein einziger Masterschlüssel", "Unsignierte Updates", "Updates per USB-Stick"], "Ein gestohlener Schlüssel reicht nicht."),
   mc("Warum sind Updates selbst ein Risiko?", ["Ungeschützte Updates könnten manipuliert sein", "Weil sie zu klein sind", "Weil sie Benzin verbrauchen", "Weil sie das Radio stören"], "Deshalb Signaturen und Prüfungen."),
   mc("Wo wird der Versionszähler für Anti-Rollback gespeichert?", ["Im geschützten Speicher", "Im Handschuhfach", "Auf dem Display", "In der Cloud-Werbung"], "Er darf nicht manipulierbar sein.")]),
 L("sec.m5.l3", "Gateway und Funkschnittstellen", 6, [
  "Ein zentrales Gateway ist die Firewall des Fahrzeugs.",
  "## Netztrennung",
  "Infotainment, Telematik und Diagnose liegen in eigenen Netzen. Das Gateway lässt nur definierte Botschaften und Dienste durch, und zwar nur in der nötigen Richtung. Ein kompromittiertes Infotainment soll so keine Bremsbotschaften senden können.",
  "## Funkschnittstellen",
  "Bluetooth, WLAN, Mobilfunk, Schlüsselfunk, Reifendrucksensoren und V2X sind aus der Ferne erreichbar. Maßnahmen: aktuelle Protokollversionen, Authentisierung beim Koppeln, Härtung der Software (unnötige Dienste abschalten), Isolation per Virtualisierung und regelmäßige Updates.",
  "## Ladeschnittstelle",
  "Beim Laden kommunizieren Fahrzeug und Ladesäule, etwa nach ISO 15118 mit Plug & Charge über Zertifikate. Auch diese Schnittstelle gehört in die Risikoanalyse."],
  ["Gateway: Netztrennung, Filter nach Botschaft, Dienst und Richtung.", "Funkschnittstellen härten, authentisieren, isolieren, aktualisieren.", "Ladeschnittstelle (ISO 15118) ist Teil der Analyse."],
  [S_21434],
  [card("Netztrennung", "Aufteilung in getrennte Netze mit kontrollierten Übergängen."), card("Härtung", "Reduzieren der Angriffsfläche, z. B. durch Abschalten unnötiger Dienste."), card("ISO 15118", "Norm für Kommunikation zwischen Fahrzeug und Ladesäule, inklusive Plug & Charge.")],
  [mc("Was soll die Netztrennung verhindern?", ["Dass ein gekapertes Infotainment Bremsbotschaften sendet", "Dass das Radio lauter wird", "Dass Reifen platzen", "Dass der Tank leer wird"], "Das Gateway filtert streng."),
   mc("Was ist Härtung?", ["Unnötige Dienste abschalten", "Stahl verstärken", "Reifen aufpumpen", "Lack versiegeln"], "Weniger Angriffsfläche."),
   mc("Welche Norm regelt Plug & Charge?", ["ISO 15118", "ISO 26262", "SAE J1962", "ISO 14229"], "Mit Zertifikaten zwischen Fahrzeug und Ladesäule."),
   multi("Welche Schnittstellen sind aus der Ferne erreichbar?", ["Bluetooth", "Mobilfunk", "Reifendrucksensor-Funk", "Interne Busleitung im Motorraum"], [0, 1, 2], "Die Busleitung braucht physischen Zugang."),
   mc("Was filtert ein Gateway zusätzlich zur Botschaft?", ["Die Richtung", "Die Farbe", "Die Temperatur", "Den Kraftstoff"], "Manche Daten dürfen nur in eine Richtung fließen.")])
])

M6 = M("sec.m6", 3, "Im Betrieb: erkennen und reagieren", "Angriffserkennung, Security Operations, Schwachstellen und Tests.", [
 L("sec.m6.l1", "Angriffe erkennen", 6, [
  "Kein Schutz ist perfekt. Deshalb müssen Angriffe im Feld erkannt werden, wie es R155 verlangt.",
  "## Intrusion Detection",
  "Ein Intrusion Detection System (IDS) im Fahrzeug beobachtet den Busverkehr und das Verhalten von Steuergeräten: unbekannte Botschafts-IDs, falsche Zykluszeiten, plötzliche Lastspitzen, fehlgeschlagene Authentisierungen, ungewöhnliche Diagnoseanfragen. In AUTOSAR gibt es dafür den IdsM, der Sicherheitsereignisse sammelt.",
  "## Melden statt eingreifen",
  "Meist reagiert das IDS nicht selbst, sondern meldet Auffälligkeiten an das Backend. Ein automatischer Eingriff könnte selbst ein Sicherheitsrisiko sein, etwa wenn eine legitime Botschaft fälschlich blockiert wird.",
  "## Fehlalarme",
  "Gute Erkennung braucht ein genaues Bild des Normalverhaltens. Sonst erzeugt sie viele Fehlalarme, die echte Angriffe verdecken."],
  ["IDS beobachtet Busverkehr und Steuergeräteverhalten.", "Meist melden statt eingreifen.", "Normalverhalten genau kennen, sonst Fehlalarme."],
  [S_AUTOSAR, S_R155],
  [card("IDS", "Intrusion Detection System: erkennt Anzeichen von Angriffen."), card("IdsM", "AUTOSAR Intrusion Detection System Manager: sammelt und filtert Sicherheitsereignisse.")],
  [multi("Welche Auffälligkeiten erkennt ein Fahrzeug-IDS?", ["Unbekannte Botschafts-IDs", "Falsche Zykluszeiten", "Fehlgeschlagene Authentisierungen", "Leerer Wischwassertank"], [0, 1, 2], "Der Wischwassertank ist kein Sicherheitsereignis."),
   mc("Warum greift ein IDS meist nicht selbst ein?", ["Ein Fehleingriff könnte gefährlich sein", "Weil es keinen Strom hat", "Weil es verboten ist zu melden", "Weil es zu langsam ist"], "Lieber melden und Experten bewerten lassen."),
   mc("Wohin meldet das IDS?", ["An das Backend des Herstellers", "An die Polizei direkt", "An das Radio", "An den Fahrer per SMS"], "Dort werden Meldungen ausgewertet."),
   mc("Was braucht gute Erkennung?", ["Ein genaues Bild des Normalverhaltens", "Möglichst viele Fehlalarme", "Keine Daten", "Einen lauten Alarm"], "Sonst gehen echte Angriffe unter."),
   mc("Welche Regelung verlangt Erkennung im Feld?", ["UN R155", "Euro 7", "SAE J1962", "ISO 15765"], "Überwachen und reagieren über den Lebenszyklus.")]),
 L("sec.m6.l2", "Vehicle SOC und Vorfälle", 6, [
  "Meldungen aus Millionen Fahrzeugen landen in einem Vehicle Security Operations Center (VSOC).",
  "## Aufgaben",
  "Meldungen sammeln und korrelieren (passiert das gleiche in vielen Fahrzeugen?), Bedrohungsinformationen auswerten, Vorfälle bewerten und Reaktionen auslösen.",
  "## Reaktion",
  "Je nach Schwere: Beobachten, Backend-Dienste anpassen, Zertifikate sperren, Software-Update entwickeln und verteilen, im Extremfall Funktionen abschalten oder Fahrzeuge zurückrufen. Behörden müssen informiert werden, wenn es Vorschriften verlangen.",
  "## Lernen",
  "Jeder Vorfall fließt zurück in die Entwicklung: TARA aktualisieren, Schutzmaßnahmen verbessern, Tests ergänzen."],
  ["VSOC sammelt, korreliert und bewertet Meldungen.", "Reaktionen: Zertifikate sperren, Updates, ggf. Rückruf.", "Vorfälle fließen zurück in TARA und Entwicklung."],
  [S_R155, S_21434],
  [card("VSOC", "Vehicle Security Operations Center: zentrale Stelle zur Überwachung und Reaktion auf Angriffe."), card("Korrelation", "Verknüpfen vieler Meldungen, um Muster und Kampagnen zu erkennen.")],
  [mc("Was macht ein VSOC?", ["Meldungen sammeln, bewerten, reagieren", "Fahrzeuge lackieren", "Reifen wechseln", "Abgase messen"], "Zentrale Überwachung der Flotte."),
   mc("Warum korreliert man Meldungen?", ["Um Muster in vielen Fahrzeugen zu erkennen", "Um Speicher zu sparen", "Für die Statistik der Farben", "Um Fahrer zu bewerten"], "Ein Einzelfall kann Zufall sein, eine Welle eher nicht."),
   mc("Welche Reaktion ist bei einem gestohlenen Zertifikat sinnvoll?", ["Zertifikat sperren", "Nichts tun", "Alle Fahrzeuge verschrotten", "Den Fahrer anrufen"], "Sperrlisten machen es wertlos."),
   mc("Was passiert nach einem Vorfall in der Entwicklung?", ["TARA und Maßnahmen werden aktualisiert", "Nichts", "Die Abteilung wird geschlossen", "Die Software wird gelöscht"], "Lernen aus Vorfällen."),
   mc("Was ist die stärkste Reaktion?", ["Funktionen abschalten oder Rückruf", "Beobachten", "Eine E-Mail schreiben", "Ein Plakat aufhängen"], "Nur bei schweren Fällen.")]),
 L("sec.m6.l3", "Schwachstellen und Tests", 6, [
  "Sicherheit wird geprüft, bevor und nachdem Fahrzeuge auf die Straße kommen.",
  "## Tests in der Entwicklung",
  "Code-Analyse, Prüfen der Sicherheitsanforderungen, Fuzzing (Schnittstellen mit zufälligen oder fehlerhaften Eingaben bombardieren) und Penetrationstests, bei denen Fachleute wie Angreifer vorgehen.",
  "## Schwachstellenmanagement",
  "Software enthält Fremdkomponenten (Open Source, Zulieferer). Eine Liste aller Bestandteile (Software Bill of Materials, SBOM) hilft, schnell zu sehen, welche Fahrzeuge von einer neu bekannten Lücke betroffen sind.",
  "## Coordinated Disclosure",
  "Viele Hersteller bieten Sicherheitsforschern einen Meldeweg an, manche zahlen Prämien (Bug Bounty). Gefundene Lücken werden zuerst vertraulich gemeldet und erst nach Behebung veröffentlicht."],
  ["Tests: Code-Analyse, Fuzzing, Penetrationstests.", "SBOM zeigt betroffene Fahrzeuge bei neuen Lücken.", "Coordinated Disclosure und Bug Bounty."],
  [S_21434],
  [card("Fuzzing", "Test mit zufälligen oder fehlerhaften Eingaben, um Abstürze und Lücken zu finden."), card("Penetrationstest", "Gezielter Angriffstest durch Fachleute."), card("SBOM", "Software Bill of Materials: Liste aller Softwarebestandteile."), card("Coordinated Disclosure", "Vertrauliche Meldung einer Lücke, Veröffentlichung erst nach Behebung.")],
  [mc("Was ist Fuzzing?", ["Test mit zufälligen oder fehlerhaften Eingaben", "Polieren von Steckern", "Messung des Reifendrucks", "Ein Abgastest"], "Findet Abstürze und unerwartetes Verhalten."),
   mc("Wozu dient eine SBOM?", ["Betroffene Fahrzeuge bei Lücken schnell finden", "Ersatzteile bestellen", "Kraftstoff abrechnen", "Fahrzeuge lackieren"], "Sie listet alle Softwarebestandteile."),
   mc("Was bedeutet Coordinated Disclosure?", ["Erst vertraulich melden, später veröffentlichen", "Sofort im Internet veröffentlichen", "Nie melden", "Nur dem Fahrer sagen"], "Zeit zum Beheben, bevor Angreifer davon wissen."),
   mc("Wer führt Penetrationstests durch?", ["Fachleute, die wie Angreifer vorgehen", "Die Kunden beim Kauf", "Der Gesetzgeber", "Die Lackiererei"], "Kontrolliert und beauftragt."),
   mc("Was ist ein Bug Bounty?", ["Prämie für gemeldete Lücken", "Ein Strafzettel", "Ein Insektenschutz", "Ein Rabatt für Neuwagen"], "Belohnt verantwortungsvolle Forschung.")])
])

COURSE = {"id": "sec", "title": "Automotive Security",
  "sub": "Angriffe verstehen und abwehren: R155, R156, ISO/SAE 21434, TARA, Kryptografie, sichere Diagnose und Updates",
  "audience": "Alle, die verstehen wollen, wie Fahrzeuge gegen Cyberangriffe geschützt werden",
  "modules": [M1, M2, M3, M4, M5, M6]}
